//! SCF energies, analytical gradients and Hessians against PySCF reference data
//! (tests/data/scf_reference.json, Cartesian basis functions, generated by tests/reference/gen_scf.py).

use hf_rs::{
    build_basis, compute_hessian_with_charge, compute_rhf_gradient, compute_uhf_gradient, get_builtin_basis,
    run_scf_general, run_uhf, Atom, ConvAlgo,
};

struct Case {
    name: String,
    basis: String,
    atoms: Vec<Atom>,
    charge: i32,
    spin: usize,
    energy: f64,
    gradient: Vec<[f64; 3]>,
    hessian: Vec<Vec<f64>>,
}

fn load_cases() -> Vec<Case> {
    let data: serde_json::Value = serde_json::from_str(include_str!("data/scf_reference.json")).unwrap();
    let mut cases = Vec::new();
    for (name, sys) in data["systems"].as_object().unwrap() {
        let atoms: Vec<Atom> = sys["geometry_bohr"]
            .as_str()
            .unwrap()
            .split(';')
            .map(|tok| {
                let p: Vec<&str> = tok.split_whitespace().collect();
                Atom::new(p[0], [p[1].parse().unwrap(), p[2].parse().unwrap(), p[3].parse().unwrap()])
            })
            .collect();
        for (basis, r) in sys["results"].as_object().unwrap() {
            let to_vec = |v: &serde_json::Value| -> Vec<f64> {
                v.as_array().unwrap().iter().map(|x| x.as_f64().unwrap()).collect()
            };
            cases.push(Case {
                name: name.clone(),
                basis: basis.clone(),
                atoms: atoms.clone(),
                charge: sys["charge"].as_i64().unwrap() as i32,
                spin: sys["spin_2s"].as_u64().unwrap() as usize,
                energy: r["energy"].as_f64().unwrap(),
                gradient: r["gradient"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|g| {
                        let g = to_vec(g);
                        [g[0], g[1], g[2]]
                    })
                    .collect(),
                hessian: r["hessian"].as_array().unwrap().iter().map(to_vec).collect(),
            });
        }
    }
    cases
}

fn max_abs_diff(a: &[[f64; 3]], b: &[[f64; 3]]) -> f64 {
    a.iter()
        .zip(b)
        .flat_map(|(x, y)| (0..3).map(move |k| (x[k] - y[k]).abs()))
        .fold(0.0, f64::max)
}

#[test]
fn scf_energy_and_gradient_match_pyscf() {
    let mut failures = Vec::new();
    for c in load_cases() {
        let basis_map = get_builtin_basis(&c.basis).unwrap();
        let basis = build_basis(&c.atoms, &basis_map);
        let (energy, grad) = if c.spin == 0 {
            let hf = run_scf_general(&c.atoms, &basis, c.charge, 200, 1e-12, ConvAlgo::Cdiis, None).unwrap();
            (hf.total_energy, compute_rhf_gradient(&c.atoms, &basis, &hf))
        } else {
            let uhf = run_uhf(&c.atoms, &basis, c.charge, c.spin + 1, false, 200, 1e-12).unwrap();
            (uhf.total_energy, compute_uhf_gradient(&c.atoms, &basis, &uhf))
        };
        let de = (energy - c.energy).abs();
        let dg = max_abs_diff(&grad, &c.gradient);
        let gsum: f64 = (0..3).map(|k| grad.iter().map(|g| g[k]).sum::<f64>().abs()).fold(0.0, f64::max);
        println!("{:4} {:7} dE = {:.2e}  dG = {:.2e}  |sum G| = {:.2e}", c.name, c.basis, de, dg, gsum);
        if de > 1e-8 || dg > 1e-6 || gsum > 1e-9 {
            failures.push(format!("{}/{}: dE={:.2e} dG={:.2e} sumG={:.2e}", c.name, c.basis, de, dg, gsum));
        }
    }
    assert!(failures.is_empty(), "mismatches: {:#?}", failures);
}

#[test]
fn rhf_analytical_hessian_matches_pyscf() {
    let mut failures = Vec::new();
    for c in load_cases().into_iter().filter(|c| c.spin == 0) {
        let basis_map = get_builtin_basis(&c.basis).unwrap();
        let h = compute_hessian_with_charge(&c.atoms, &basis_map, c.charge, 200, 1e-12);
        let n = 3 * c.atoms.len();
        let mut worst = 0.0_f64;
        for i in 0..n {
            for j in 0..n {
                worst = worst.max((h[(i, j)] - c.hessian[i][j]).abs());
            }
        }
        println!("{:4} {:7} max |dH| = {:.2e}", c.name, c.basis, worst);
        if worst > 1e-5 {
            failures.push(format!("{}/{}: {:.2e}", c.name, c.basis, worst));
        }
    }
    assert!(failures.is_empty(), "Hessian mismatches: {:#?}", failures);
}
